-- PWD-1 shoppers, one per case that changes (or might change) a password, so no case depends on another's change
-- and none signs in as alice or bob. Every user starts with the password Factoryfake1$ (the hash below is the
-- ASP.NET Identity V3 hash of that clear text, from `factory teststack hash-password`), EmailConfirmed = true,
-- LockoutEnabled = true and AccessFailedCount = 0.
-- pwd1-menu: TC-PWD-1-01, TC-PWD-1-12: menu entry and sign-in redirect; never submits a change
INSERT INTO public."AspNetUsers" ("Id", "CardNumber", "SecurityNumber", "Expiration", "CardHolderName", "CardType", "Street", "City", "State", "Country", "ZipCode", "Name", "LastName", "UserName", "NormalizedUserName", "Email", "NormalizedEmail", "EmailConfirmed", "PasswordHash", "SecurityStamp", "ConcurrencyStamp", "PhoneNumber", "PhoneNumberConfirmed", "TwoFactorEnabled", "LockoutEnd", "LockoutEnabled", "AccessFailedCount") VALUES ('00000000-0000-0000-0001-000000000001', 'XXXXXXXXXXXX1881', '123', '12/30', 'Pwd One', 1, '15703 NE 61st Ct', 'Redmond', 'WA', 'U.S.', '98052', 'Pwd', 'One', 'pwd1-menu', 'PWD1-MENU', 'pwd1-menu@example.test', 'PWD1-MENU@EXAMPLE.TEST', true, 'AQAAAAIAAYagAAAAEFOvCpCY9d17gz4HUubVzKbiKebgUzNa9OlzVafrhN4+b7Kw6qMhbHR5WT82IzKkyQ==', 'PWD1STAMP01XXXXXXXXXXXXXXXXXXXXX', '00000000-0000-0000-0002-000000000001', '1234567890', false, false, NULL, true, 0);
